    40: 39, // Jigglypuff -> Wigglytuff
    45: 44, // Gloom -> Vileplume
    59: 58, // Growlithe -> Arcanine
    62: 61, // Poliwhirl -> Poliwrath
    65: 64, // Kadabra -> Alakazam
    68: 67, // Machoke -> Machamp
    71: 70, // Weepinbell -> Victreebel
    76: 75, // Graveler -> Golem
    91: 90, // Shellder -> Cloyster
    94: 93, // Haunter -> Gengar
    103: 102, // Exeggcute -> Exeggutor
    121: 120, // Staryu -> Starmie
    134: 133, // Eevee -> Vaporeon
    135: 133, // Eevee -> Jolteon
    136: 133, // Eevee -> Flareon
  };

  static int? _findPreEvolutionId(int speciesId) {
    final special = _specialPreEvolutionIds[speciesId];
    if (special != null) return special;
    for (final s in species.values) {
      if (s.evolutionSpeciesId == speciesId) return s.id;
    }
    return null;
  }

  static List<PokemonSpecies> evolutionLineUpTo(PokemonSpecies spec) {
    final List<PokemonSpecies> chain = [];
    final Set<int> visited = {};
    PokemonSpecies? curr = spec;
    while (curr != null && visited.add(curr.id)) {
      chain.insert(0, curr);
      final prevId = _findPreEvolutionId(curr.id);
      curr = prevId != null ? species[prevId] : null;
    }
    return chain;
  }

  static List<Move> movesForSpeciesAtLevel(PokemonSpecies spec, int level) {
    final List<Move> unlocked = [];
    for (final lm in spec.learnset) {
      if (lm.level <= level && moves.containsKey(lm.moveId)) {
        unlocked.removeWhere((m) => m.id == lm.moveId);
        unlocked.add(moves[lm.moveId]!.copy());
      }
    }
    if (unlocked.length > 4) {
      return unlocked.sublist(unlocked.length - 4);
    }
    return unlocked;
  }

  static List<Move> movesUnlockedAtExactLevel(PokemonSpecies spec, int level) {
    return spec.learnset
        .where((lm) => lm.level == level && moves.containsKey(lm.moveId))
        .map((lm) => moves[lm.moveId]!.copy())
        .toList();
  }

  static List<String> learnedMoveIdsUpToLevel(PokemonSpecies spec, int level) {
    final List<String> ids = [];
    for (final stage in evolutionLineUpTo(spec)) {
      for (final lm in stage.learnset) {
        if (lm.level <= level &&
            moves.containsKey(lm.moveId) &&
            !ids.contains(lm.moveId)) {
          ids.add(lm.moveId);
        }
      }
    }
    return ids;
  }

  static const List<int> firstStageFossilSpeciesIds = [138, 140, 142];
  static const int shinyOddsDenominator = 4096;

  static const Map<int, int> tradeEvolutionTargets = {
    64: 65, // Kadabra -> Alakazam
    67: 68, // Machoke -> Machamp
    75: 76, // Graveler -> Golem
    93: 94, // Haunter -> Gengar
  };

  static int? getTradeEvolutionTarget(int speciesId) =>
      tradeEvolutionTargets[speciesId];

  static String? evolutionRequirementLabel(PokemonSpecies spec) {
    if (spec.evolutionSpeciesId != null && spec.evolutionLevel != null) {
      final next = species[spec.evolutionSpeciesId!];
      return "Evolves into ${next?.name ?? 'next form'} at Level ${spec.evolutionLevel}";
    }
    const specialHints = {
      25: 'Evolves into Raichu via Thunder Stone',
      30: 'Evolves into Nidoqueen via Moon Stone',
      33: 'Evolves into Nidoking via Moon Stone',
      35: 'Evolves into Clefable via Moon Stone',
      37: 'Evolves into Ninetales via Fire Stone',
      39: 'Evolves into Wigglytuff via Moon Stone',
      44: 'Evolves into Vileplume via Leaf Stone',
      58: 'Evolves into Arcanine via Fire Stone',
      61: 'Evolves into Poliwrath via Water Stone',
      64: 'Evolves into Alakazam via Link Trade (Fist Bump)',
      67: 'Evolves into Machamp via Link Trade (Fist Bump)',
      70: 'Evolves into Victreebel via Leaf Stone',
      75: 'Evolves into Golem via Link Trade (Fist Bump)',
      90: 'Evolves into Cloyster via Water Stone',
      93: 'Evolves into Gengar via Link Trade (Fist Bump)',
      102: 'Evolves into Exeggutor via Leaf Stone',
      120: 'Evolves into Starmie via Water Stone',
      133: 'Evolves into Vaporeon / Jolteon / Flareon via Evolution Stone',
    };
    return specialHints[spec.id];
  }

  static int shinyOddsForSpecies(PokemonSpecies species) {
    if (species.isLegendary || species.isMythical) {
      return shinyOddsDenominator * 2; // 1/8192 for Legendaries & Mythicals
    }
    return shinyOddsDenominator; // 1/4096 regular rate
  }

  static bool rollShiny(PokemonSpecies species) {
    if (!species.isShinyEligible) return false;
    return _rng.nextInt(shinyOddsForSpecies(species)) == 0;
  }

  static ({int slot, String id}) rollAbility(
    PokemonSpecies species, {
    double hiddenAbilityChance = 0.02,
  }) {
    return PokemonInstance.rollAbilityForSpecies(
      species,
      hiddenChance: hiddenAbilityChance,
      rng: _rng,
    );
  }

  static PokemonInstance createPokemon(
    int speciesId, {
    int level = 5,
    String? nickname,
    bool respectMinEncounterLevel = true,
    bool isShiny = false,
    String? abilityId,
    int? abilitySlot,
    double hiddenAbilityChance = 0.02,
  }) {
    final spec = species[speciesId]!;
    final effectiveLevel =
        (respectMinEncounterLevel && level < spec.minEncounterLevel)
            ? spec.minEncounterLevel
            : level;
    final rolled = rollAbility(spec, hiddenAbilityChance: hiddenAbilityChance);
    final int resolvedSlot = abilitySlot ??
        (abilityId != null ? spec.slotForAbility(abilityId) : rolled.slot);
    final String resolvedAbility = abilityId ?? spec.abilityForSlot(resolvedSlot);
    return PokemonInstance(
      species: spec,
      nickname: nickname,
      level: effectiveLevel,
      moves: movesForSpeciesAtLevel(spec, effectiveLevel),
      isShiny: isShiny && spec.isShinyEligible,
      abilityId: resolvedAbility,
      abilitySlot: resolvedSlot,
    );
  }

  // ─── STARTER FACTORY ──────────────────────────────────────────────────
  static PokemonInstance createStarter(int speciesId, {String? nickname}) {
    final spec = species[speciesId]!;
    return createPokemon(
      speciesId,
      level: 5,
      nickname: nickname,
      isShiny: rollShiny(spec),
      hiddenAbilityChance: 0.05,
    );
  }

  static PokemonRarity rollEncounterRarity([double? roll]) {
    final double r = roll ?? _rng.nextDouble();
    if (r < 0.65) return PokemonRarity.common;
    if (r < 0.95) return PokemonRarity.uncommon;
    return PokemonRarity.rare;
  }

  static List<PokemonSpecies> speciesForRarity(
    PokemonRarity rarity, {
    int? playerLevel,
    GameVersion? gameVersion,
  }) {
    return species.values.where((s) {
      if (s.rarity != rarity) return false;
      if (!s.isWildEncounterable) return false;
      if (!s.isAvailableInVersion(gameVersion)) return false;
      if (playerLevel != null &&
          !s.canEncounterAtPlayerLevel(playerLevel, gameVersion: gameVersion)) {
        return false;
      }
      return true;
    }).toList();
  }

  // ─── WILD ENCOUNTER GENERATOR ─────────────────────────────────────────
  static PokemonInstance generateWildEncounter({
    int playerLevel = 5,
    GameVersion? gameVersion,
  }) {
    // 65% Common (1st stage), 30% Uncommon (2nd stage within 5 levels),
    // 5% Rare (1st stage starters, 3rd stage, final pseudo-legendary within 10 levels).
    final targetRarity = rollEncounterRarity();
    final rarityPool = speciesForRarity(
      targetRarity,
      playerLevel: playerLevel,
      gameVersion: gameVersion,
    );
    final eligiblePool = species.values
        .where((s) =>
            s.canEncounterAtPlayerLevel(playerLevel, gameVersion: gameVersion))
        .toList();
    final pool = rarityPool.isNotEmpty
        ? rarityPool
        : (eligiblePool.isNotEmpty
            ? eligiblePool
            : species.values
                .where((s) =>
                    s.isWildEncounterable &&
                    s.isAvailableInVersion(gameVersion))
                .toList());
    final chosen = pool[_rng.nextInt(pool.length)];

    final baseMin = (playerLevel - 2).clamp(2, 99);
    final baseMax = (playerLevel + 1).clamp(baseMin, 100);
    final minLvl = max(baseMin, chosen.minEncounterLevel).clamp(2, 100);
    final maxLvl = max(baseMax, minLvl).clamp(minLvl, 100);
    final level = minLvl + _rng.nextInt(maxLvl - minLvl + 1);
    final bool isShiny = rollShiny(chosen);
    return createPokemon(chosen.id, level: level, isShiny: isShiny);
  }

  // ─── RIVAL POKÉMON GENERATOR ──────────────────────────────────────────
  static PokemonInstance generateRivalPokemon({int playerLevel = 5}) {
    final level = (playerLevel + 1).clamp(5, 100);
    final List<int> rivalPool = [
      // Starters scaled to level
      level >= 32 ? 3 : (level >= 16 ? 2 : 1),
      level >= 36 ? 6 : (level >= 16 ? 5 : 4),
      level >= 36 ? 9 : (level >= 16 ? 8 : 7),
      // Iconic Gen 1 Kanto rival picks across all lines
      level >= 36 ? 18 : (level >= 18 ? 17 : 16),
      level >= 20 ? 20 : 19,
      level >= 20 ? 22 : 21,
      level >= 22 ? 24 : 23,
      level >= 22 ? 26 : 25,
      level >= 22 ? 28 : 27,
      level >= 36 ? 31 : (level >= 16 ? 30 : 29),
      level >= 36 ? 34 : (level >= 16 ? 33 : 32),
      level >= 26 ? 36 : 35,
      level >= 24 ? 40 : 39,
      level >= 22 ? 42 : 41,
      level >= 36 ? 45 : (level >= 21 ? 44 : 43),
      level >= 24 ? 47 : 46,
      level >= 26 ? 51 : 50,
      level >= 28 ? 53 : 52,
      level >= 28 ? 57 : 56,
      level >= 36 ? 62 : (level >= 25 ? 61 : 60),
      level >= 36 ? 65 : (level >= 16 ? 64 : 63),
      level >= 38 ? 68 : (level >= 28 ? 67 : 66),
      level >= 36 ? 71 : (level >= 21 ? 70 : 69),
      level >= 38 ? 76 : (level >= 25 ? 75 : 74),
      83,
      level >= 28 ? 91 : 90,
      level >= 38 ? 94 : (level >= 25 ? 93 : 92),
      95,
      level >= 26 ? 97 : 96,
      level >= 28 ? 99 : 98,
      level >= 30 ? 101 : 100,
      level >= 33 ? 119 : 118,
      level >= 26 ? 121 : 120,
      122,
      // Newly added Gen 1 iconic rivals
      level >= 22 ? 38 : 37,
      level >= 31 ? 49 : 48,
      level >= 33 ? 55 : 54,
      level >= 24 ? 59 : 58,
      level >= 30 ? 73 : 72,
      level >= 40 ? 78 : 77,
      level >= 37 ? 80 : 79,
      level >= 30 ? 82 : 81,
      level >= 31 ? 85 : 84,
      level >= 34 ? 87 : 86,
      level >= 38 ? 89 : 88,
      level >= 26 ? 103 : 102,
      level >= 28 ? 105 : 104,
      106,
      107,
      108,
      level >= 35 ? 110 : 109,
      level >= 42 ? 112 : 111,
      113,
      114,
      115,
      level >= 32 ? 117 : 116,
      123,
      124,
      125,
      126,
      127,
      128,
      131,
      132,
      level >= 25 ? 134 : 133,
      level >= 25 ? 135 : 133,
      level >= 25 ? 136 : 133,
      137,
      level >= 40 ? 139 : 138,
      level >= 40 ? 141 : 140,
      142,
      143,
      level >= 55 ? 149 : (level >= 30 ? 148 : 147),
    ];

    if (level >= 10) rivalPool.addAll([12, 15]);
    if (level >= 20) rivalPool.add(130);

    final eligibleRivalIds = rivalPool.where((id) {
      final spec = species[id];
      return spec != null &&
          level >= spec.minEncounterLevel &&
          playerLevel >= spec.requiredPlayerLevelForEncounter;
    }).toList();
    final finalPool = eligibleRivalIds.isNotEmpty ? eligibleRivalIds : rivalPool;

    final speciesId = finalPool[_rng.nextInt(finalPool.length)];
    return createPokemon(
      speciesId,
      level: level,
      nickname: "Rival's ${species[speciesId]!.name}",
    );
  }
}
